const planningIds=['sleep','nutrition','quality','budget','used','recovery','effortKind','learning','connection','joy','meaning','moodDo','moodAlt','altMinutes','altMoney','altEffort','priority','horizon','laterDo','laterAlt','confidence','decisionType','purchaseReason','uses','funding','savingFor','goalRemaining','monthlySaving','interest','comfortableSpend','bestOutcome','hardOutcome','supportPlan','smallOption','smallMinutes','smallMoney','smallBenefit','annualGoal','annualIncome','workHours','workWeeks'];
const moods={'-2':'much worse','-1':'a little worse','0':'about the same','1':'a little better','2':'much better',unknown:'uncertain'};
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(n);
function energyPlan(){const duration=Number($('minutes').value)||0,recovery=Number($('recovery').value)||0,total=duration+recovery;let text=`${duration} minutes for the option + ${recovery} minutes to recover = ${total} minutes to allow.`;if($('budget').value!==''){const remaining=Math.max(0,Number($('budget').value)-Number($('used').value||0)),balance=remaining-total;text+=` Of your self-chosen time budget, ${remaining} minutes remain before this option. ${balance>=0?balance+' minutes would remain afterward.':'This plan exceeds it by '+Math.abs(balance)+' minutes.'}`}else{text+=' Enter your own comfortable time budget to compare; sleep does not set it automatically.'}return {text,total}}
function updateEnergy(){put('energyEstimate',energyPlan().text)}['budget','used','recovery','minutes'].forEach(id=>$(id).addEventListener('input',updateEnergy));updateEnergy();
function changeType(){const type=$('decisionType').value;['purchase','relationship'].forEach(t=>{const f=$(t+'Fields');f.hidden=type!==t;f.disabled=type!==t})} $('decisionType').addEventListener('change',changeType);
function addPerspective(){if(!current)return;planningIds.forEach(id=>current[id]=$(id).value);const d=current,p=energyPlan();const priorities={balance:'balancing today and the future',recovery:'recovery and feeling better today',connection:'connection and belonging',future:'learning and future opportunities'};put('summary',p.text+` You describe your capacity as “${capacities[d.capacity-1].toLowerCase()}” and the option’s effort as “${levels[d.energy-1].toLowerCase()}.” These are self-reports, not measured energy.`);put('cost',`${d.minutes} minutes + ${d.recovery} recovery · ${money(Number(d.money||0))} · effort: ${levels[d.energy-1].toLowerCase()}`);put('happiness',`Now: you expect to feel ${moods[d.moodDo]} after this option and ${moods[d.moodAlt]} after the alternative. In ${d.horizon}: this option looks ${moods[d.laterDo]}, the alternative ${moods[d.laterAlt]}. Your confidence is ${d.confidence}. Your priority is ${priorities[d.priority]}.`);const names={learning:'learning / future value',connection:'connection / belonging',joy:'enjoyment / mood',meaning:'meaning / accomplishment'};const benefits=Object.keys(names).filter(k=>Number(d[k])>0).sort((a,b)=>Number(d[b])-Number(d[a]));put('benefits',benefits.length?'Benefits you anticipate: '+benefits.map(k=>`${names[k]} (${d[k]}/5)`).join('; ')+'.':'No benefits rated yet. It is okay to be unsure.');const dt=Number(d.minutes)-Number(d.altMinutes),dm=Number(d.money||0)-Number(d.altMoney);put('resourceCompare',`Before recovery time, this option takes ${Math.abs(dt)} minutes ${dt>=0?'more':'less'} and costs ${money(Math.abs(dm))} ${dm>=0?'more':'less'} than the alternative. Alternative effort: ${levels[d.altEffort-1].toLowerCase()}.`);
let question='Which expectation is least certain, and what small step could give you useful information?';if(d.priority==='recovery'||Number(d.energy)>Number(d.capacity))question='What smaller version keeps a benefit you care about without stretching how you feel today?';$('scenarioResult').hidden=d.decisionType==='everyday';put('scenarioText','');put('scenarioMath','');put('scenarioNote','');
if(d.decisionType==='purchase'){put('scenarioHeading','Buy now or save for later');const reasons={use:'frequent use, comfort, or quality',expression:'self-expression or meaning',status:'how others see you',occasion:'a special occasion',unsure:'an unclear benefit'};put('scenarioText',`You are buying for ${reasons[d.purchaseReason]}. Compare that with ${d.savingFor||'the future use of the money you would keep'}. Your feelings now and in ${d.horizon} may differ; neither is automatically more important.`);let math=[];if(d.uses!=='')math.push(`At ${d.uses} expected uses, the purchase price is ${money(Number(d.money||0)/Number(d.uses))} per use, excluding upkeep and resale.`);if(d.goalRemaining!==''&&Number(d.monthlySaving)>0){const remaining=Number(d.goalRemaining),monthly=Number(d.monthlySaving),base=remaining/monthly;math.push(`At ${money(monthly)} per month, the remaining ${money(remaining)} goal takes about ${base.toFixed(1)} months before any purchase.`);if(d.funding==='savings')math.push(`If the full ${money(Number(d.money||0))} purchase comes from money earmarked for that goal, the shortfall would take about ${(Number(d.money||0)/monthly).toFixed(1)} extra months of contributions to replace.`);else math.push('No goal delay is calculated because you did not select goal savings as the funding source.')}else if(d.goalRemaining!==''||d.monthlySaving!=='')math.push('Enter the amount still needed and a positive monthly contribution to estimate goal timing.');put('scenarioMath',math.join(' '));put('scenarioNote',d.funding==='debt'?'Borrowing can add costs that are not included here. Check the actual interest and fees before treating this purchase price as its full cost.':d.funding==='unsure'?'Check where this money would come from before deciding whether it fits.':'The arithmetic compares uses of money. It does not predict happiness or prove affordability.');question=d.purchaseReason==='status'?'Would you still want this if nobody knew the brand or price?':'After the novelty fades, what will you still enjoy—and is that worth what saving would preserve?'}
if(d.decisionType==='relationship'){put('scenarioHeading','Connection with room for uncertainty');const states={unknown:'You do not yet know whether interest is mutual.',mutual:'You report that they have expressed interest too.',unclear:'You describe the signals as mixed.',declined:'They have declined or asked for space. Respect that boundary; do not use more gifts or invitations to change their answer.'};put('scenarioText',states[d.interest]+` A hoped-for outcome: ${d.bestOutcome.replace(/[.!?]+$/,'')||'not entered'}. A difficult outcome: ${d.hardOutcome.replace(/[.!?]+$/,'')||'not entered'}.`);put('scenarioMath',d.comfortableSpend!==''?`You entered ${money(Number(d.comfortableSpend))} as an amount you would feel okay giving without a romantic outcome. This option costs ${money(Number(d.money||0))}; ${Number(d.money||0)>Number(d.comfortableSpend)?'it exceeds that limit.':'it is within that limit.'}`:'Choose a time and money limit you would still feel comfortable with if the answer is no.');put('scenarioNote',`Your support plan: ${d.supportPlan.replace(/[.!?]+$/,'')||'not entered yet'}. Gifts create no obligation, and rejection odds are unknown. Choosing not to pursue can preserve resources and can also mean missing a chance for connection.`);question=d.interest==='declined'?'What would help you step back and care for yourself while respecting their answer?':'Would a clear, low-pressure invitation give you the connection or clarity you want without a large emotional or financial commitment?'}
$('smallResult').hidden=!d.smallOption;if(d.smallOption)put('smallText',`${d.smallOption} · ${d.smallMinutes!==''?d.smallMinutes+' minutes':'time not estimated'} · ${d.smallMoney!==''?money(Number(d.smallMoney)):'cost not estimated'}. ${d.smallBenefit||'Consider which benefits it keeps and what you give up.'}`);if(d.decisionType==='relationship'&&d.interest==='declined'){ $('smallResult').hidden=false;put('smallText','Step back from pursuing this person. A smaller next step could be time with a friend or a plan that helps you recover, without another invitation or gift.')}put('question',question);d.profileSummary=[$('happiness').textContent,$('resourceCompare').textContent,p.text,$('scenarioText').textContent,$('scenarioMath').textContent,d.smallOption?'Smaller option: '+$('smallText').textContent:''].filter(Boolean).join('\n\n');}
$('form').addEventListener('submit',addPerspective);
function loadExample(values){$('form').reset();Object.entries(values).forEach(([k,v])=>$(k).value=v);changeType();ranges();updateEnergy();incomeContext();$('form').requestSubmit()}
$('example').addEventListener('click',()=>{Object.entries({sleep:7,nutrition:'regular',quality:'okay',budget:240,used:90,recovery:30,learning:4,connection:4,joy:3,meaning:3,moodDo:1,moodAlt:1,altMinutes:90,altMoney:0,priority:'connection',laterDo:1,laterAlt:0,smallOption:'Attend the key part and say hello to a friend',smallMinutes:75,smallMoney:6,smallBenefit:'Keep the learning and a little connection, with less time on campus.'}).forEach(([k,v])=>$(k).value=v);changeType();updateEnergy();addPerspective()});
$('purchaseExample').onclick=()=>loadExample({decisionType:'purchase',task:'Buy a luxury jacket',alt:'Keep $400 toward my travel fund',minutes:60,money:400,energy:2,capacity:3,gain:'Enjoy wearing it and feel more like myself.',skip:'I keep wearing my current jacket and preserve my travel savings.',repeat:'once',joy:4,meaning:2,moodDo:2,moodAlt:0,laterDo:1,laterAlt:2,horizon:'six months',confidence:'low',altMinutes:5,altMoney:0,altEffort:1,purchaseReason:'expression',uses:50,funding:'savings',savingFor:'A trip with friends',goalRemaining:1200,monthlySaving:200,smallOption:'Try it on, wait a week, and look for a secondhand option',smallMinutes:30,smallMoney:0,smallBenefit:'Learn whether I still want it after the initial excitement.'});
$('relationshipExample').onclick=()=>loadExample({decisionType:'relationship',task:'Invite someone I like to dinner',alt:'Step back and spend the evening with a friend',minutes:120,money:80,energy:4,capacity:3,recovery:30,gain:'A chance to connect and understand whether interest is mutual.',skip:'I avoid the immediate uncertainty but may still wonder.',repeat:'once',connection:5,joy:3,meaning:3,moodDo:1,moodAlt:1,laterDo:'unknown',laterAlt:'unknown',confidence:'low',altMinutes:90,altMoney:15,altEffort:2,priority:'connection',interest:'unknown',comfortableSpend:30,bestOutcome:'A comfortable conversation and interest in meeting again.',hardOutcome:'They decline, and I feel sad or embarrassed.',supportPlan:'Talk to a friend and leave some space to decompress.',smallOption:'Ask once whether they would like a short coffee',smallMinutes:30,smallMoney:10,smallBenefit:'Keep a chance for connection and clarity with less pressure.'});
$('reset').addEventListener('click',()=>{changeType();updateEnergy();incomeContext()});
function incomeContext(){const goal=Number($('annualGoal').value),income=Number($('annualIncome').value),hours=Number($('workHours').value),weeks=Number($('workWeeks').value);if(!goal||hours<=0||weeks<=0){put('incomeContext','Enter a goal and positive work hours and weeks to see equivalents.');return}put('incomeContext',`${money(goal)} per year is about ${money(goal/12)} per month or ${money(goal/(hours*weeks))} per paid hour before taxes at your entered schedule.`+($('annualIncome').value?` Your entered income is ${money(Math.abs(goal-income))} ${income<goal?'below':income===goal?'equal to':'above'} this personal goal.`:''))}['annualGoal','annualIncome','workHours','workWeeks'].forEach(id=>$(id).addEventListener('input',incomeContext));
